const rule = $input.item.json;
const entities = rule.entities || [];

if (entities.length === 0) return [{ json: { skip: true, reason: 'No entities', rule } }];

const token = entities[0]?.token || null;
if (!token) return [{ json: { skip: true, reason: 'No token', rule } }];

const conditions = rule.conditions || [];
const needsMultiDay = conditions.some(c => c.lookback === 'last_3d' || c.lookback === 'last_7d');

const batch = [
  ...entities.map(e => ({ method: 'GET', relative_url: `${e.entityId}?fields=effective_status,name` })),
  ...entities.map(e => ({ method: 'GET', relative_url: `${e.entityId}/insights?fields=spend,actions,action_values,purchase_roas,cost_per_action_type&date_preset=today` })),
  ...(needsMultiDay ? entities.map(e => ({ method: 'GET', relative_url: `${e.entityId}/insights?fields=spend,actions,action_values,purchase_roas,cost_per_action_type&date_preset=last_3_days` })) : []),
];

return [{ json: { rule, entities, batch, token, needsMultiDay } }];

const { rule, entities, token, needsMultiDay } = $('Build FB Batch').item.json;
const responses = $('FB Batch API').all().map(i => i.json);
const n = entities.length;

function parseInsights(resp) {
  if (!resp || resp.code !== 200) return null;
  let body; try { body = JSON.parse(resp.body); } catch { return null; }
  const d = body?.data?.[0];
  if (!d) return null;
  const spend = parseFloat(d.spend || 0);
  const conversions = parseFloat(d.actions?.find(a => a.action_type === 'purchase')?.value || 0);
  const cpa = conversions > 0 ? spend / conversions : 0;
  const roas = parseFloat(d.purchase_roas?.[0]?.value || 0);
  const purchaseValue = parseFloat(d.action_values?.find(a => a.action_type === 'purchase')?.value || 0);
  const roi = spend > 0 ? (purchaseValue - spend) / spend : 0;
  return { spend_today: spend, conversions, cpa, roas, roi };
}

const conditions = rule.conditions || [];
const combinator = rule.combinator || 'AND';
const triggered = [];

for (let i = 0; i < n; i++) {
  const entity = entities[i];
  const entityId = entity.entityId;
  const entityToken = entity.token || token;

  const statusResp = responses[i];
  let entityName = entityId;
  if (statusResp?.code === 200) {
    let sb; try { sb = JSON.parse(statusResp.body); } catch {}
    entityName = sb?.name || entityId;
    if (sb?.effective_status === 'PAUSED' && rule.action !== 'enable') continue;
  }

  const todayInsights = parseInsights(responses[n + i]);
  const multiInsights = needsMultiDay ? parseInsights(responses[2 * n + i]) : todayInsights;
  if (!todayInsights) continue;

  const evaluate = (c) => {
    const src = (c.lookback === 'last_3d' || c.lookback === 'last_7d') ? multiInsights : todayInsights;
    const val = src?.[c.metric];
    if (val === undefined || val === null) return false;
    switch (c.operator) {
      case 'gt':  return val > c.value;
      case 'lt':  return val < c.value;
      case 'gte': return val >= c.value;
      case 'lte': return val <= c.value;
      case 'eq':  return val === c.value;
      default:    return false;
    }
  };

  const allMet = combinator === 'OR' ? conditions.some(evaluate) : conditions.every(evaluate);
  if (allMet) {
    triggered.push({ json: { rule, entityId, entityName, metrics: todayInsights, token: entityToken } });
  }
}

// Account cap: aggregate total spend across all entities
if (rule.scope === 'account' && conditions.length > 0) {
  const totalSpend = triggered.reduce((sum, t) => sum + (t.json.metrics.spend_today || 0), 0);
  const condition = conditions[0];
  if (condition && totalSpend > condition.value) {
    return [{ json: { rule, entityId: 'ALL', entityName: 'All Campaigns', metrics: { spend_today: totalSpend }, token, isAccountCap: true } }];
  }
  return [{ json: { noTrigger: true } }];
}

return triggered.length > 0 ? triggered : [{ json: { noTrigger: true } }];

const d = $input.item.json;
const resp = await fetch(`${$env.ZUCKCANNON_URL}/api/rules-engine/pause-pending/check?rule_id=${d.rule.id}&entity_id=${encodeURIComponent(d.entityId)}`, { headers: { 'x-n8n-secret': $env.ZUCKCANNON_SECRET } });
const result = await resp.json();
return [{ json: { ...d, pending: result.pending } }];

const d = $input.item.json;
const resp = await fetch(`${$env.ZUCKCANNON_URL}/api/rules-engine/exemptions/check?rule_id=${d.rule.id}&entity_id=${encodeURIComponent(d.entityId)}`, { headers: { 'x-n8n-secret': $env.ZUCKCANNON_SECRET } });
const result = await resp.json();
return [{ json: { ...d, exempt: result.exempt } }];

const d = $input.item.json;
try {
  const resp = await fetch(`https://graph.facebook.com/v25.0/${d.entityId}?fields=learning_stage_info&access_token=${encodeURIComponent(d.token)}`);
  const result = await resp.json();
  return [{ json: { ...d, learning_stage_info: result.learning_stage_info || null } }];
} catch(e) {
  return [{ json: { ...d, learning_stage_info: null } }];
}

const { rule, entityId, entityName, metrics, token } = $input.item.json;

let body = {};
if (rule.action === 'pause') body = { status: 'PAUSED', access_token: token };
else if (rule.action === 'enable') body = { status: 'ACTIVE', access_token: token };
// scale_budget: handled by Fetch Current Budget → Compute Scale Budget → Call FB API Scale

return [{ json: { entityId, entityName, body, rule, metrics, token } }];

const d = $input.item.json;
const body = `access_token=${encodeURIComponent(d.token)}&status=${encodeURIComponent(d.body.status)}`;
const resp = await fetch(`https://graph.facebook.com/v25.0/${d.entityId}`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body
});
const result = await resp.json();
return [{ json: { ...d, fbResult: result } }];

const d = $input.item.json;
const resp = await fetch(`https://graph.facebook.com/v25.0/${d.entityId}?fields=daily_budget&access_token=${encodeURIComponent(d.token)}`);
const result = await resp.json();
return [{ json: { ...d, daily_budget: result.daily_budget } }];

const { entityId, entityName, rule, metrics, token, daily_budget } = $input.item.json;
const currentBudgetCents = parseInt(daily_budget || 0);
const scaledCents = Math.round(currentBudgetCents * 1.2);
const maxCents = rule.action_params?.max_budget ? rule.action_params.max_budget * 100 : Infinity;
const newBudgetCents = Math.min(scaledCents, maxCents);
return [{ json: { entityId, entityName, rule, metrics, token, newBudgetCents } }];

const d = $input.item.json;
const body = `access_token=${encodeURIComponent(d.token)}&daily_budget=${d.newBudgetCents}`;
const resp = await fetch(`https://graph.facebook.com/v25.0/${d.entityId}`, {
  method: 'POST',
  headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  body
});
const result = await resp.json();
return [{ json: { ...d, fbResult: result } }];

